package android.app;import android.content.*;public class WallpaperManager {public static final int FLAG_LOCK=2;public static int installed=3;private Context context;private WallpaperManager(Context c){context=c;}public static WallpaperManager getInstance(Context c){return new WallpaperManager(c);}public WallpaperInfo getWallpaperInfo(){return getWallpaperInfo(1);}public WallpaperInfo getWallpaperInfo(int flag){return (installed&flag)!=0?new WallpaperInfo(new ComponentName(context,dev.workshopvideo.VideoWallpaperService.class)):null;}public int getWallpaperId(int flag){return (installed&flag)!=0?100+flag:-1;}}